/* =========================================================
   FTC Handbook — glossary
   Every key here becomes a clickable term across the site.
   app.js auto-tags the first appearance of each term (or any
   alias) inside each section. To add a word:
     key: { term: "Shown name", aliases: ["other spellings"],
            def: "One or two plain sentences.", see: ["otherKey"], link: "page.html#id" }
   Keep defs short. Mid-level vocab. No paragraphs.
   ========================================================= */
window.GLOSSARY = {
  /* ---- programs & culture ---- */
  "ftc": { term: "FTC", aliases: ["FIRST Tech Challenge"], def: "FIRST Tech Challenge. A robotics league for grades 7–12 where teams build an 18-inch robot from off-the-shelf and custom parts, then compete in 2-vs-2 alliance matches and judged awards.", see: ["frc", "fll", "first"] },
  "frc": { term: "FRC", aliases: ["FIRST Robotics Competition"], def: "FIRST Robotics Competition. The high-school league above FTC. Bigger robots (around 120 lb), bigger budgets, a six-week-plus build season starting in January.", see: ["ftc"] },
  "fll": { term: "FLL", aliases: ["FIRST LEGO League"], def: "FIRST LEGO League. The LEGO-based program for elementary and middle school. FTC teams often mentor FLL teams as outreach.", see: ["ftc", "outreach"] },
  "first": { term: "FIRST", def: "For Inspiration and Recognition of Science and Technology. The nonprofit that runs FLL, FTC, and FRC. Its stated goal is to get students excited about STEM, not just to hold robot contests." },
  "gp": { term: "Gracious Professionalism", aliases: ["GP", "gracious professional"], def: "FIRST's core value. Compete hard, but treat opponents, volunteers, and judges with respect and help other teams when you can. Judges watch for it all day, not just in the interview.", see: ["coopertition"] },
  "coopertition": { term: "Coopertition", def: "Cooperating with other teams even while competing against them. Sharing a spare part, helping an alliance partner fix their robot, or lending a battery all count." },
  "outreach": { term: "outreach", def: "Anything your team does to spread STEM or FIRST beyond the team itself: demos, mentoring, workshops, sponsor pitches. Judges want numbers and proof, not adjectives.", see: ["connect-award", "motivate-award"] },
  "mentor": { term: "mentor", def: "An adult (or older student) who guides the team. In FTC the students should still make the decisions and do the work. Judges can tell when they did not." },
  "leadership-award": { term: "FIRST Leadership Award", aliases: ["Dean's List", "Leadership Award"], def: "The individual award that replaced Dean's List in 2025. Teams nominate two 10th or 11th graders for leadership and technical contribution. Nominations open in September and close mid-December.", link: "judging.html#awards" },

  /* ---- season & competition ---- */
  "kickoff": { term: "kickoff", def: "The day the new game is revealed, normally the first Saturday after Labor Day. The Competition Manual, field drawings, and game animation drop at the same time." },
  "competition-manual": { term: "Competition Manual", aliases: ["game manual", "Game Manual Part 1", "Game Manual Part 2"], def: "The official rulebook for the season. One document covers robot rules, game rules, tournament rules, and judged awards. Read it. Then read the Q&A forum where it gets clarified." },
  "gm0": { term: "Game Manual 0", aliases: ["gm0"], def: "gm0.org. A community-written guide to building and programming an FTC robot. Not official, but the best single starting point for mechanisms, drivetrains, software basics, and awards." },
  "qa-forum": { term: "Q&A forum", aliases: ["Q&A system"], def: "The official FIRST question-and-answer site where teams ask about rules. Answers there are binding on referees and inspectors." },
  "match": { term: "match", def: "One game, about 2.5 minutes long: a 30-second autonomous period, then a 2-minute driver-controlled period whose last 30 seconds is the endgame.", see: ["autonomous", "teleop", "endgame"] },
  "autonomous": { term: "autonomous", aliases: ["auto", "auton"], def: "The first 30 seconds of a match. The robot runs entirely on pre-written code, no driver input. Good autos score a lot of points and set up the rest of the match.", see: ["teleop"] },
  "teleop": { term: "TeleOp", aliases: ["driver-controlled period", "tele-op"], def: "The two-minute driver-controlled period after autonomous. Two drivers per team use gamepads to run the robot.", see: ["autonomous", "endgame"] },
  "endgame": { term: "endgame", def: "The final 30 seconds of TeleOp. Most games add special high-value tasks here, like climbing or parking." },
  "alliance": { term: "alliance", def: "Two teams paired together for a match, red or blue. In qualification matches your partner is random. In playoffs, alliance captains pick their partners.", see: ["alliance-selection"] },
  "alliance-selection": { term: "alliance selection", aliases: ["alliance captain", "pick list"], def: "After qualification matches, the top-ranked teams become captains and take turns choosing partners for the playoffs. Having a scouting pick list ready matters here.", see: ["scouting"] },
  "qualification": { term: "qualification matches", aliases: ["quals", "qualifying matches"], def: "The randomly paired matches that determine event rankings before playoffs." },
  "playoffs": { term: "playoffs", aliases: ["elimination matches", "elims"], def: "The bracket after alliance selection. The winning alliance and finalists earn advancement points." },
  "ranking-points": { term: "ranking points", aliases: ["RP"], def: "Points that decide event rankings. Exactly how they are earned is game-specific and defined in the Competition Manual." },
  "league-meet": { term: "league meet", def: "A small, low-stakes event in regions that use the league system. Matches count toward league ranking but there is no judging." },
  "league-tournament": { term: "league tournament", def: "The end-of-league event with judging, alliance selection, and advancement. Sometimes called a league championship." },
  "qualifier": { term: "qualifier", aliases: ["qualifying tournament"], def: "A one-day tournament in regions that do not use leagues. Judging, matches, awards, and advancement all happen the same day." },
  "championship": { term: "regional championship", aliases: ["state championship", "regional", "super-regional"], def: "The next level up from your qualifier or league tournament. Teams advance from here to the FIRST Championship.", see: ["worlds"] },
  "worlds": { term: "FIRST Championship", aliases: ["Worlds", "World Championship"], def: "The season-ending international event in Houston each April. Only a small fraction of teams advance." },
  "advancement": { term: "advancement", aliases: ["advancement points"], def: "Since 2025 there is no ordered list. Teams earn points at each event (Inspire 60/30/15, other awards 12/6/3, playoffs 40/20/10/5, alliance captain and draft picks, qualification rank) and the top totals in a region move on.", link: "judging.html#advancement" },
  "inspection": { term: "inspection", aliases: ["robot inspection"], def: "The safety and rules check every robot passes before it can compete. Size, weight, wiring, motor count, and the Robot Controller app version all get checked.", see: ["sizing-cube"] },
  "sizing-cube": { term: "sizing cube", aliases: ["18-inch cube", "18\" cube", "starting configuration"], def: "The 18 × 18 × 18 inch volume your robot must fit inside at the start of a match (R102). After the start it may expand to 18 × 24 inches horizontally and 29 inches tall (R105), limited mechanically, not by software.", link: "design.html#rules" },
  "scouting": { term: "scouting", def: "Watching other teams' matches and pits and writing down what they can actually do. Used to pick alliance partners and plan match strategy.", see: ["alliance-selection"] },
  "opr": { term: "OPR", def: "Offensive Power Rating. A statistic that estimates how many points a team contributes per match, computed from alliance scores. FTCScout publishes it." },
  "cycle-time": { term: "cycle time", aliases: ["cycle"], def: "How long it takes to grab one game element and score it. Shave a second off your cycle and you gain several points per match. Usually the most important robot metric.", link: "season.html#cycle" },
  "game-element": { term: "game element", aliases: ["game piece", "scoring element"], def: "The objects the game asks you to move and score: rings, cones, pixels, samples. Each season has a new one." },
  "field": { term: "field", aliases: ["playing field"], def: "A 12 × 12 foot area of foam tiles inside low walls. Field drawings come out at kickoff so you can measure everything in CAD." },
  "penalty": { term: "penalty", aliases: ["minor foul", "major foul", "foul"], def: "Points given to the other alliance when you break a rule. Minor and major fouls have different values set each season." },
  "reveal": { term: "reveal video", aliases: ["robot reveal"], def: "A short video teams post showing their finished robot. The best ones, along with the FTC Discord robot showcase, are where design ideas spread." },

  /* ---- judging & awards ---- */
  "portfolio": { term: "Engineering Portfolio", aliases: ["portfolio"], def: "The only judged document: one cover page plus up to 15 content pages, US Letter or A4, covering work from January 1 of the kickoff year onward. Required for Inspire, Think, and Control; helpful for everything else.", link: "judging.html#portfolio" },
  "notebook": { term: "Engineering Notebook", aliases: ["notebook", "EN"], def: "The team's running record of meetings, decisions, tests, and failures. No longer required or collected by the manual, but it is where every portfolio page and interview answer comes from. Keep one.", see: ["portfolio"] },
  "judging-interview": { term: "Initial Interview", aliases: ["judging interview", "judge interview", "Structured Interview", "interview"], def: "The mandatory judging session: at least 10 minutes with two or three judges, about five minutes of uninterrupted presentation, then questions. At least two students; the robot is optional. Events may run it scheduled, at the pit, or by video.", link: "judging.html#interview" },
  "pit": { term: "pit", aliases: ["pits"], def: "Your team's work area at an event. Judges walk the pits and ask follow-up questions, so keep someone there who can answer." },
  "rubric": { term: "award criteria", aliases: ["rubric", "judging rubric", "Required criteria", "Encouraged criteria"], def: "Each judged award lists numbered Required and Encouraged criteria in the Competition Manual (Tables 6-2 to 6-9). The old Beginning / Developing / Accomplished / Exemplary ladder is history. Write the portfolio to the criteria.", link: "judging.html#rubrics" },
  "inspire-award": { term: "Inspire Award", def: "The top judged award, for the team that is a strong contender for Think, a Team Attribute award, and a Machine award at once, and shows FIRST values. Worth 60 advancement points to the winner. Portfolio required.", link: "judging.html#awards" },
  "think-award": { term: "Think Award", def: "Rewards the documented engineering process: evidence of process, lessons learned, comparing options, and math-based decisions. Judged from the portfolio and interview. Portfolio required.", link: "judging.html#awards" },
  "connect-award": { term: "Connect Award", def: "A Team Attribute award for partnerships with the engineering and STEM community, plus a plan to develop the team's skills. Mentors, sponsors, shop access, and what you learned from each.", link: "judging.html#awards" },
  "innovate-award": { term: "Innovate Award", def: "A Machine award, sponsored by RTX, for a creative and working robot design or mechanism that solves a game challenge in a new way.", link: "judging.html#awards" },
  "control-award": { term: "Control Award", def: "A Machine award for sensors and software that make the robot more effective. The portfolio must summarize each control component, the problem it solves, and how it works. There is no longer a separate submission form.", link: "judging.html#awards" },
  "motivate-award": { term: "Motivate Award", def: "Retired after the 2024–25 season. Its ground was split into the Reach Award (bringing new people into FIRST) and the Sustain Award (organizational and financial sustainability).", see: ["reach-award", "sustain-award"], link: "judging.html#awards" },
  "reach-award": { term: "Reach Award", def: "A Team Attribute award, new in 2025, for bringing new people into FIRST: recruiting, starting teams, mentoring FLL, demos that led to sign-ups. Judges want counts and outcomes.", link: "judging.html#awards" },
  "sustain-award": { term: "Sustain Award", def: "A Team Attribute award, new in 2025, for organizational, financial, and leadership sustainability: budget, funding plan, leadership pipeline, surviving graduation.", link: "judging.html#awards" },
  "judges-choice": { term: "Judges' Choice Award", aliases: ["Judges' Choice"], def: "An optional, discretionary award for something the judges want to recognize that no other award covers. Since 2025 it earns advancement points like the other non-Inspire awards.", link: "judging.html#awards" },
  "design-award": { term: "Design Award", def: "A Machine award for industrial design: a robot that is functional, well built, and looks intentional, with a clear design process behind it.", link: "judging.html#awards" },
  "promote-award": { term: "Promote Award", def: "The video award from earlier seasons. It is not in the 2025–26 or 2026–27 award list, so treat it as retired.", link: "judging.html#awards" },
  "compass-award": { term: "Compass Award", def: "An optional award for an outstanding mentor, nominated by students with a 40–60 second video. Offered at regional championships and the FIRST Championship.", link: "judging.html#awards" },
  "business-plan": { term: "business plan", aliases: ["team plan", "sustainability plan", "strategic plan"], def: "A short document covering how the team recruits, funds itself, and keeps going after seniors graduate. Judges for Connect look for it." },
  "sponsor": { term: "sponsor", aliases: ["sponsorship"], def: "A company, organization, or person who gives the team money, parts, or shop access. Document what they gave and what you did with it." },

  /* ---- design fundamentals ---- */
  "kiss": { term: "KISS", aliases: ["keep it simple"], def: "Keep it simple, stupid. The design rule that wins FTC. Simple mechanisms get built on time, get tested more, and break less.", link: "design.html#principles" },
  "touch-it-own-it": { term: "touch it, own it", aliases: ["touch it own it"], def: "The intake principle: the moment your robot touches a game element it should already have control of it. Rollers and compliant wheels do this. A slow pincher does not.", link: "design.html#intakes" },
  "buildability": { term: "buildability", def: "How easy a design is to physically assemble, take apart, and fix. Screw access, part count, and clear CAD all matter. Ask the builders before you finalize." },
  "cots": { term: "COTS", aliases: ["commercial off-the-shelf"], def: "Commercial off-the-shelf. Parts you can buy from a vendor as-is. FTC allows almost any COTS part as long as it follows the robot rules, like the one-degree-of-freedom limit on pre-built mechanisms." },
  "dof": { term: "degree of freedom", aliases: ["degrees of freedom", "DOF"], def: "One independent way something can move. A wheel on an axle has one, a ball joint has three. FTC uses the term in robot rules (COTS mechanisms) and Onshape uses it for sketches and mates." },
  "drivetrain": { term: "drivetrain", aliases: ["drive base", "chassis"], def: "The wheels, motors, and frame that move the robot around the field. Everything else bolts onto it, so it is the first thing to get right.", link: "design.html#drivetrains" },
  "holonomic": { term: "holonomic", def: "A drivetrain that can move in any direction without turning first: forward, sideways, diagonal, and spin, all at once. Mecanum, X-drive, and swerve are holonomic. Tank is not." },
  "mecanum": { term: "mecanum", aliases: ["mecanum drive", "mecanum wheels", "mecanum wheel"], def: "Wheels with rollers set at 45 degrees. Drive all four the right way and the robot can strafe sideways. The default FTC drivetrain: four motors, simple code, decent pushing power.", link: "design.html#drivetrains" },
  "tank-drive": { term: "tank drive", aliases: ["skid steer", "standard drive"], def: "Wheels on the left and right driven separately, like a tank. Simple and strong but it cannot strafe, so lining up takes longer." },
  "swerve": { term: "swerve", aliases: ["swerve drive", "coaxial swerve"], def: "Each wheel can steer independently. Fast and precise, but each module needs its own steering actuator, custom parts, and a lot of code. Rarely worth it in FTC.", link: "design.html#drivetrains" },
  "diffy-swerve": { term: "differential swerve", aliases: ["diffy swerve", "diffy"], def: "A swerve module where two motors drive a differential: spin them together to steer, spin them opposite to drive. Very cool, very hard. Plan on months of pre-season work.", see: ["swerve"] },
  "x-drive": { term: "X-drive", def: "Four omni wheels mounted at 45 degrees in an X. Holonomic and fast, but low traction and a big footprint." },
  "kiwi-drive": { term: "kiwi drive", def: "Three omni wheels in a triangle. Compact and holonomic, but only three motors of traction and awkward math." },
  "h-drive": { term: "H-drive", def: "A tank drive with one or two extra sideways wheels in the middle for strafing. Simple to code, but the middle wheel takes up space and has weak traction." },
  "omni-wheel": { term: "omni wheel", aliases: ["omni wheels", "omniwheel"], def: "A wheel with small rollers around its rim set at 90 degrees, so it rolls freely sideways. Used in X-drives, kiwi drives, and dead-wheel odometry pods." },
  "traction-wheel": { term: "traction wheel", aliases: ["grip wheel"], def: "A plain rubber wheel. Best pushing force, no sideways motion." },
  "intake": { term: "intake", def: "The mechanism that grabs game elements off the field. Active intakes use spinning rollers or wheels. Passive intakes rely on driving into the element.", link: "design.html#intakes" },
  "compliant-wheel": { term: "compliant wheel", aliases: ["compliant wheels", "flex wheel"], def: "A squishy rubber wheel that deforms around a game element and grips it. The standard active-intake part in FTC." },
  "counter-roller": { term: "counter rollers", aliases: ["counter roller", "counter-roller"], def: "Two rollers spinning toward each other so the element gets pulled between them. Very controlled, but needs more power and space than one roller." },
  "claw": { term: "claw", aliases: ["gripper", "pincher"], def: "A servo-driven gripper that pinches a game element. Precise and simple, but it has to be lined up on the element first, which costs time." },
  "end-effector": { term: "end effector", def: "Whatever sits at the end of your arm or slide and actually touches the game element: a claw, roller, or magnet." },
  "four-bar": { term: "four-bar linkage", aliases: ["4-bar", "four-bar", "4 bar"], def: "Two parallel arms joining a base to a moving plate. When the arms are the same length the plate stays level as it swings, which is perfect for carrying game elements.", link: "design.html#arms" },
  "virtual-four-bar": { term: "virtual four-bar", aliases: ["virtual 4-bar", "V4B"], def: "A single arm where a belt or chain, anchored to the base, turns the end effector the opposite way so it stays level. Same result as a four-bar with fewer parts.", see: ["four-bar"] },
  "linear-slide": { term: "linear slide", aliases: ["linear slides", "slides", "viper slide", "misumi slide"], def: "Telescoping rails on bearings that extend in a straight line. The standard FTC lift and reach mechanism. Driven by string, belt, or rack.", link: "design.html#linear" },
  "cascade-rigging": { term: "cascade rigging", aliases: ["cascade"], def: "Slide stages rigged so every stage extends at the same time. Fast and the string sees low load, but the stages have to be rigged carefully.", see: ["continuous-rigging"] },
  "continuous-rigging": { term: "continuous rigging", aliases: ["continuous"], def: "Slide stages rigged so they extend one after another. Simpler string path, more lift force, slower top speed.", see: ["cascade-rigging"] },
  "rack-and-pinion": { term: "rack and pinion", def: "A gear (pinion) rolling along a straight toothed bar (rack) to make linear motion. Strong and direct, but limited to the rack's length." },
  "turret": { term: "turret", def: "A rotating platform that swings a mechanism side to side without turning the whole robot. Saves alignment time, adds a bearing and a motor." },
  "flywheel": { term: "flywheel", aliases: ["shooter"], def: "A fast-spinning wheel that flings a game element. Consistency depends on wheel speed, so pair it with an encoder and velocity control." },
  "scissor-lift": { term: "scissor lift", def: "Criss-crossed arms that extend upward. Looks great, wobbles a lot, and eats power at the bottom of its travel. Almost always the wrong choice." },
  "differential": { term: "differential", def: "A gearbox that splits or combines two inputs. Used in differential swerve and in some clever two-motor arms." },
  "ratchet": { term: "ratchet", aliases: ["sprag", "sprag clutch", "one-way bearing"], def: "A mechanism that lets a shaft spin one way but locks the other. Lets one motor drive two mechanisms, or holds a lift without stalling the motor." },

  /* ---- power transmission ---- */
  "gear-ratio": { term: "gear ratio", aliases: ["reduction", "gear reduction"], def: "Output teeth divided by input teeth. A 3:1 ratio spins the output three times slower and gives it about three times the torque. Same math for sprockets and pulleys.", link: "design.html#gearing" },
  "torque": { term: "torque", def: "Rotational force. Measured in N·m or kg·cm. More torque means a mechanism can lift or push more. Trade speed for it through gearing.", see: ["gear-ratio"] },
  "stall-torque": { term: "stall torque", def: "The torque a motor produces when it is loaded so hard it stops turning. Never run near it for long; the motor heats up fast and the current spikes.", see: ["stall-current"] },
  "free-speed": { term: "free speed", aliases: ["no-load speed"], def: "How fast a motor spins with nothing attached, in RPM. Real speed under load is lower, roughly half at peak power." },
  "backlash": { term: "backlash", def: "The slop between gear teeth (or in a chain). Reverse direction and the output does nothing for a moment. Printed gears and long gear trains make it worse; tight tolerances and belts make it better.", link: "design.html#problems" },
  "spur-gear": { term: "spur gear", aliases: ["spur gears", "spur"], def: "The plain flat gear with straight teeth. Efficient and cheap, needs careful center distance or you get backlash and skipping." },
  "bevel-gear": { term: "bevel gear", aliases: ["bevel gears", "bevel", "miter gear"], def: "A cone-shaped gear that turns motion 90 degrees. Two identical ones are called miter gears." },
  "worm-gear": { term: "worm gear", aliases: ["worm gears", "worm drive", "worm"], def: "A screw driving a gear. Huge reduction in one stage, and the output cannot back-drive the input, so arms hold position with the motor off. Inefficient and it wears." },
  "helical-gear": { term: "helical gear", aliases: ["helical", "herringbone"], def: "Gears with angled teeth for smoother, quieter meshing. Herringbone gears are two helicals back to back so the side loads cancel." },
  "planetary": { term: "planetary gearbox", aliases: ["planetary"], def: "A compact gearbox with a sun gear, planet gears, and a ring gear. Almost every FTC motor (Yellow Jacket, UltraPlanetary) has one built in." },
  "cycloidal": { term: "cycloidal drive", aliases: ["cycloidal"], def: "A high-reduction gearbox using an off-center lobed disc. Low backlash and strong, but a project on its own." },
  "capstan": { term: "capstan drive", aliases: ["capstan"], def: "A cable wrapped around two drums to transfer motion. Zero backlash and very light, but limited travel and needs constant tension." },
  "chain": { term: "chain", aliases: ["roller chain", "sprocket"], def: "Sprockets and chain. Strong and easy to change ratios, but it stretches, needs tensioning, and can derail if misaligned. #25 chain is the FTC size." },
  "belt": { term: "belt", aliases: ["timing belt", "GT2", "HTD", "pulley"], def: "Toothed belts on pulleys. Quiet, low backlash, and they slip instead of breaking your motor on a hard stop. Center distance has to be exact." },
  "direct-drive": { term: "direct drive", def: "Wheel or mechanism mounted straight on the motor shaft. No backlash and nothing to break, but every impact goes into the gearbox." },
  "hex-shaft": { term: "hex shaft", aliases: ["REX shaft", "5mm hex"], def: "A six-sided shaft that keys into hubs without set screws. 5 mm hex is the FTC standard for goBILDA and REV." },
  "d-shaft": { term: "D-shaft", def: "A round shaft with one flat, held with a set screw. Common on servos and some motors, prone to slipping under load." },
  "bearing": { term: "bearing", aliases: ["ball bearing", "flanged bearing"], def: "A ring of balls that lets a shaft spin with almost no friction and takes side load. Use one on every rotating shaft that carries load." },
  "bushing": { term: "bushing", def: "A plain sleeve (often Delrin or bronze) a shaft slides in. Cheaper and thinner than a bearing, more friction." },
  "tensioner": { term: "tensioner", def: "An adjustable idler or slot that takes slack out of a chain or belt. Design it in from the start; you will need it." },

  /* ---- materials & manufacturing ---- */
  "extrusion": { term: "extrusion", aliases: ["aluminum extrusion", "channel", "U-channel", "goRAIL"], def: "Long aluminum profiles with a repeating hole pattern. goBILDA channel and REV extrusion are the two systems FTC teams build frames from.", link: "manufacturing.html#systems" },
  "grid-pattern": { term: "grid pattern", aliases: ["8mm grid", "hole pattern"], def: "The repeating hole spacing on a build system. goBILDA uses an 8 mm grid with 4 mm holes, so anything you design on that grid bolts straight on." },
  "polycarbonate": { term: "polycarbonate", aliases: ["Lexan", "polycarb"], def: "A tough, clear plastic sheet you can cut, drill, and bend by hand. Great for guards, ramps, and side plates. Does not shatter like acrylic." },
  "delrin": { term: "Delrin", aliases: ["acetal", "POM"], def: "A slippery, stiff plastic used for bushings, sliders, and gears. Machines beautifully. Does not 3D print." },
  "uhmw": { term: "UHMWPE", aliases: ["UHMW"], def: "Ultra-high-molecular-weight polyethylene. The slipperiest common plastic. Perfect for slide pads and skids." },
  "hdpe": { term: "HDPE", def: "Cheap, tough, slightly flexible plastic sheet. Good for bumpers and skid plates, too soft for precise parts." },
  "pla": { term: "PLA", def: "The easiest filament to print. Stiff but brittle and it softens around 60 °C, so keep it away from motors. Fine for prototypes and brackets that are not loaded.", link: "manufacturing.html#printing" },
  "petg": { term: "PETG", def: "The default filament for real robot parts. Tougher than PLA, handles heat better, prints with a little stringing." },
  "tpu": { term: "TPU", def: "Flexible rubber-like filament. Prints grippers, intake rollers, and bumpers. Hardness is rated on the Shore scale.", see: ["shore"] },
  "abs": { term: "ABS", aliases: ["ASA"], def: "Strong, heat-resistant filament that needs an enclosure and ventilation because it fumes. ASA is the UV-stable cousin." },
  "nylon": { term: "nylon", aliases: ["PA", "nylon-CF", "PA-CF"], def: "Tough, wear-resistant filament for gears and load-bearing parts. Absorbs moisture, so dry it before printing. Carbon-filled nylon is stiffer." },
  "shore": { term: "Shore hardness", aliases: ["Shore A", "Shore D", "Shore 00"], def: "The scale for how soft a rubber is. Lower is softer. 95A TPU is firm, 60A is squishy." },
  "infill": { term: "infill", def: "The internal fill pattern of a 3D print, as a percentage. Walls matter more for strength than infill; 3 to 4 walls at 30 percent is a good default." },
  "perimeters": { term: "walls", aliases: ["perimeters", "wall count"], def: "The solid outer shells of a 3D print. Adding walls is the most effective way to make a print stronger." },
  "layer-adhesion": { term: "layer adhesion", aliases: ["layer lines"], def: "How well print layers bond. Prints are weakest between layers, so orient the part so loads run along the layers, not across them." },
  "tolerance": { term: "tolerance", aliases: ["tolerancing"], def: "The gap you design between two parts so they actually fit after manufacturing. Printed holes come out small, so a shaft hole needs extra clearance.", link: "manufacturing.html#tolerance" },
  "clearance-fit": { term: "clearance fit", aliases: ["loose fit"], def: "A fit with a gap so parts slide or spin freely. Around 0.02 in (0.5 mm) extra for printed parts." },
  "press-fit": { term: "press fit", aliases: ["interference fit", "tight fit"], def: "A fit with no gap or a slight overlap so parts have to be pushed together and stay put. Around 0.005 in (0.1 mm) for printed parts." },
  "kerf": { term: "kerf", def: "The width of material a laser, water jet, or saw removes. Offset your cut path by half the kerf or every part comes out small." },
  "water-jet": { term: "water jet", aliases: ["waterjet"], def: "A cutter that fires high-pressure water and abrasive through sheet material. Cuts aluminum plate cleanly with no heat. The software handles kerf for you." },
  "cnc": { term: "CNC", aliases: ["CNC router", "CNC mill"], def: "Computer-controlled cutting. A CNC router or mill carves parts from plate or bar stock from a toolpath generated off your CAD." },
  "laser-cutter": { term: "laser cutter", def: "Cuts thin sheet with a laser. Great for polycarbonate, plywood, and acrylic. Never cut PVC (chlorine gas) and check that your machine can do metal before trying." },
  "sheet-metal": { term: "sheet metal", def: "Thin metal cut flat and bent into shape. Light, strong, and cheap once you have access to a cutter and a brake. Onshape has a dedicated sheet metal mode." },
  "k-factor": { term: "K-factor", def: "A number (about 0.3 to 0.5) that describes where the neutral axis sits in a bend. Sheet metal CAD uses it to compute how much the flat pattern stretches." },
  "tap": { term: "tapping", aliases: ["tap", "tapped hole", "thread"], def: "Cutting threads into a hole so a screw goes straight in with no nut. M3 and M4 taps cover most of FTC." },
  "rivet": { term: "rivet", def: "A permanent fastener set with a rivet gun. Fast and light for sheet metal and polycarb, but you drill it out to remove it." },
  "lightening": { term: "lightening", aliases: ["lightening pattern", "pocketing"], def: "Cutting holes or pockets in a part to remove weight where there is no load. Triangles and hexes are typical." },
  "fea": { term: "FEA", aliases: ["stress analysis", "simulation"], def: "Finite element analysis. Software that estimates where a part will bend or break under load. Useful for arms and plates, overkill for most FTC brackets." },
  "bom": { term: "BOM", aliases: ["bill of materials"], def: "The list of every part and quantity in an assembly. Onshape generates it from your CAD; use it to order parts and to budget." },
  "esd": { term: "ESD", aliases: ["electrostatic discharge", "static"], def: "Electrostatic discharge. Static builds up on foam tiles and zaps the Control Hub through the frame, causing disconnects. Ground the electronics to the frame the way FIRST's ESD guide describes.", link: "electronics.html#esd" },

  /* ---- Onshape ---- */
  "cad": { term: "CAD", def: "Computer-aided design. Building the robot in software first so you can check fit, generate parts to manufacture, and change one dimension without rebuilding everything." },
  "onshape": { term: "Onshape", def: "Browser-based CAD, free for students, with real-time collaboration and version history built in. The FTC standard.", link: "onshape.html" },
  "part-studio": { term: "Part Studio", def: "The Onshape tab where you sketch and build parts. One Part Studio can hold several related parts." },
  "assembly": { term: "Assembly", aliases: ["assemblies"], def: "The Onshape tab where parts get positioned and mated together so they move like the real robot." },
  "feature-tree": { term: "feature tree", aliases: ["feature list"], def: "The ordered list of every sketch and operation in a Part Studio. Onshape replays it top to bottom every time something changes, so order matters." },
  "sketch": { term: "sketch", def: "A 2D drawing on a plane that features like Extrude and Revolve turn into 3D geometry. A closed loop in a sketch is called a region." },
  "constraint": { term: "constraint", aliases: ["constraints"], def: "A rule between sketch entities: coincident, parallel, tangent, equal. Constraints state relationships. Dimensions state numbers." },
  "fully-defined": { term: "fully defined", aliases: ["fully constrained", "black sketch"], def: "A sketch with zero degrees of freedom. Every line turns black. Blue means something can still move, red means a conflict." },
  "extrude": { term: "Extrude", def: "Pushes a sketch region into 3D: add material, remove it, or make a new body. The most-used feature in Onshape." },
  "mate": { term: "mate", aliases: ["mates"], def: "The connection between two parts in an Assembly. Fastened locks them, Revolute lets them spin, Slider lets them slide." },
  "mate-connector": { term: "mate connector", aliases: ["mate connectors"], def: "A named coordinate point on a part that mates snap to. Define them in the Part Studio and assembly gets roughly ten times faster." },
  "configuration": { term: "configuration", aliases: ["configurations", "configured part"], def: "One part with several named states, like a channel in three lengths or a bracket with or without a hole. Switch states from a dropdown." },
  "variable": { term: "variable", aliases: ["variables", "Variable Studio"], def: "A named number (like #wall = 3 mm) you use in dimensions. Change it once and every feature that uses it updates. Variable Studio shares them across tabs." },
  "derive": { term: "Derive", aliases: ["derived", "skeleton model"], def: "Pulls geometry from another Part Studio as a live link. A skeleton Part Studio that holds the key dimensions, derived everywhere, keeps a whole robot in sync." },
  "in-context": { term: "in-context", aliases: ["in-context design", "in-context editing"], def: "Editing a part while seeing the assembly around it as a reference. Handy for one-off fits, fragile when several people are editing." },
  "featurescript": { term: "FeatureScript", def: "Onshape's scripting language. Every built-in feature is written in it, and the community publishes custom ones like gear and sprocket generators." },
  "version": { term: "version", aliases: ["versions", "branch", "branches"], def: "A named, permanent snapshot of an Onshape document. Branches let you try a redesign without touching the main line, then merge it back." },
  "step-file": { term: "STEP", aliases: ["STEP file", ".step"], def: "The standard file format for moving solid CAD geometry between programs. Vendors publish STEP files of their parts." },
  "stl": { term: "STL", aliases: ["3MF"], def: "A mesh file for 3D printing. Export it from CAD, open it in the slicer. 3MF is the newer format that also stores units and color." },
  "dxf": { term: "DXF", def: "A 2D vector file for laser cutting, water jetting, and CNC routing. Export flat parts as DXF." },

  /* ---- electronics ---- */
  "control-hub": { term: "Control Hub", aliases: ["REV Control Hub"], def: "The robot's brain. An Android computer plus motor, servo, and sensor ports in one box. Runs your code and talks to the Driver Station over Wi-Fi.", link: "electronics.html#control-system" },
  "expansion-hub": { term: "Expansion Hub", aliases: ["REV Expansion Hub"], def: "Adds a second set of motor, servo, and sensor ports. Connects to the Control Hub with an RS485 cable. Needed once you pass four motors." },
  "driver-hub": { term: "Driver Hub", aliases: ["REV Driver Hub", "Driver Station", "DS"], def: "The handheld Android device (or phone) the drivers plug gamepads into. It runs the Driver Station app and sends gamepad input to the Control Hub." },
  "robot-controller": { term: "Robot Controller", aliases: ["RC app", "Robot Controller app"], def: "The app on the Control Hub that runs your OpModes. Its version must match the season's minimum at inspection." },
  "servo-hub": { term: "Servo Hub", aliases: ["REV Servo Hub"], def: "A REV device that adds six more servo ports with their own power supply. Check the current Competition Manual for how it counts toward limits." },
  "servo-power-module": { term: "Servo Power Module", aliases: ["SPM"], def: "A REV board that gives servos their own beefier 6 V supply so high-torque servos do not brown out the hub." },
  "xt30": { term: "XT30", def: "The yellow two-pin power connector used on FTC batteries and hubs. Rated for 30 A. Only crimp or solder them with the right tools." },
  "jst": { term: "JST", aliases: ["JST-VH", "JST-PH"], def: "The small white connectors on hub ports. JST-VH for motors, JST-PH for sensors. Buy pre-made cables; crimping these by hand goes badly." },
  "pwm": { term: "PWM", def: "Pulse-width modulation. The signal that tells a servo where to go (or how fast, for continuous rotation). Standard hobby servos expect 500 to 2500 microsecond pulses." },
  "i2c": { term: "I²C", aliases: ["I2C"], def: "A two-wire bus for sensors like the color sensor, distance sensor, and Pinpoint. Each hub has several I²C ports; putting many sensors on one bus slows the loop." },
  "encoder": { term: "encoder", aliases: ["encoders", "motor encoder"], def: "A sensor that counts how far a shaft has turned, in ticks. Built into most FTC motors. The basis for position and velocity control.", see: ["ticks-per-rev"] },
  "ticks-per-rev": { term: "ticks per revolution", aliases: ["ticks per rev", "TPR", "CPR", "counts per revolution"], def: "How many encoder counts one full output rotation produces. Depends on the motor's gear ratio. Divide ticks by this to get rotations." },
  "through-bore": { term: "through-bore encoder", aliases: ["through bore encoder", "REV Through Bore"], def: "An encoder with a hole through the middle so a hex shaft passes straight through it. Mount it directly on the output shaft to read position without backlash." },
  "imu": { term: "IMU", aliases: ["gyro", "gyroscope"], def: "Inertial measurement unit. The gyro and accelerometer inside the Control Hub that report the robot's heading. Essential for field-centric driving and turning in autonomous." },
  "odometry": { term: "odometry", def: "Tracking robot position by counting wheel or sensor movement over time. Dead wheels, the Pinpoint, and OTOS are all odometry.", link: "code.html#localization" },
  "dead-wheel": { term: "dead wheels", aliases: ["dead wheel", "odometry pod", "odo pod", "odometry pods"], def: "Small unpowered omni wheels with encoders that ride on the floor. Because they are not driven they do not slip, so they track position far better than drive encoders." },
  "pinpoint": { term: "Pinpoint", aliases: ["goBILDA Pinpoint", "Pinpoint Odometry Computer"], def: "goBILDA's odometry computer. Plugs in two dead-wheel pods, has its own IMU, and reports the robot's x, y, and heading over I²C so the Control Hub does not have to do the math." },
  "otos": { term: "OTOS", aliases: ["SparkFun OTOS", "optical odometry"], def: "SparkFun's optical tracking odometry sensor. Reads the floor like a mouse sensor and reports position and heading. No wheels to mount, but it needs a clean view of the tiles." },
  "localization": { term: "localization", def: "Knowing where the robot is on the field. Odometry gives relative position; vision (AprilTags) gives absolute position. Good autos combine both." },
  "apriltag": { term: "AprilTag", aliases: ["AprilTags"], def: "Black-and-white square markers on the field that a camera can identify and measure distance and angle to. The SDK reads them out of the box." },
  "limelight": { term: "Limelight", aliases: ["Limelight 3A"], def: "A smart camera with its own processor that runs AprilTag and color pipelines and hands results to the Control Hub. The Limelight 3A is the only programmable vision coprocessor allowed (R702); the 3G and 4 are not.", link: "code.html#vision" },
  "color-sensor": { term: "color sensor", aliases: ["REV Color Sensor V3"], def: "A short-range sensor that reads color and rough distance. Used to detect game elements in the intake or lines on the floor." },
  "distance-sensor": { term: "distance sensor", aliases: ["2m distance sensor", "time-of-flight sensor", "ToF sensor"], def: "A laser time-of-flight sensor that measures distance up to about two meters. Slow to read, so do not poll it every loop." },
  "touch-sensor": { term: "touch sensor", aliases: ["limit switch", "magnetic limit switch"], def: "A button or magnetic switch that tells the code a mechanism hit its end of travel. Cheap insurance against tearing your own slides apart." },
  "potentiometer": { term: "potentiometer", aliases: ["pot", "analog encoder"], def: "A knob that outputs a voltage proportional to its angle. Reads absolute arm position with no homing step." },
  "servo": { term: "servo", aliases: ["servos"], def: "A small motor with position control built in. Send it an angle and it goes there. FTC allows eight (R503), each under 8 W mechanical output and 4 A stall at 6 V (R502).", link: "electronics.html#servos" },
  "cr-servo": { term: "continuous rotation servo", aliases: ["CR servo", "CRServo"], def: "A servo modified to spin continuously at a commanded speed instead of going to an angle. Handy for low-power intakes." },
  "axon": { term: "Axon", aliases: ["Axon servo", "Axon Max", "Axon Mini", "Axon Micro"], def: "High-end programmable FTC servos with fast, strong output and an analog position feedback wire. Pricey but they made a lot of claws and wrists better." },
  "yellow-jacket": { term: "Yellow Jacket", aliases: ["Yellow Jacket motor", "5203", "5204"], def: "goBILDA's planetary gearmotor line. Same motor, different gearbox ratios (from 6000 RPM bare down to 30 RPM), all with a 5 mm hex output and built-in encoder.", link: "electronics.html#motors" },
  "ultraplanetary": { term: "UltraPlanetary", aliases: ["REV UltraPlanetary"], def: "REV's stackable planetary gearbox for the HD Hex motor. Snap 3:1, 4:1, and 5:1 stages together to build your ratio." },
  "hd-hex": { term: "HD Hex motor", aliases: ["REV HD Hex", "HD Hex"], def: "REV's standard 12 V motor with a hex output. Pair it with UltraPlanetary cartridges to set the ratio." },
  "core-hex": { term: "Core Hex motor", aliases: ["Core Hex"], def: "REV's small, slow (125 RPM) 12 V motor. Fine for light mechanisms, too weak for drivetrains." },
  "stall-current": { term: "stall current", def: "The current a motor draws when stalled. For FTC motors that is around 9 to 10 A each, which is why a stalled drivetrain can brown out the whole robot." },
  "brownout": { term: "brownout", def: "Battery voltage sagging so low under load that the Control Hub or servos reset. Symptoms: random disconnects and twitching servos when the drive motors stall." },
  "fuse": { term: "fuse", aliases: ["main fuse", "circuit breaker"], def: "The 20 A protection in line with the battery, usually built into the battery or the power switch cable. Required by the robot rules." },
  "main-switch": { term: "main power switch", aliases: ["power switch", "robot switch"], def: "The single switch that cuts all power to the robot. Inspectors need to reach it fast; put it somewhere visible and labeled." },
  "awg": { term: "AWG", aliases: ["wire gauge"], def: "American Wire Gauge. Smaller number means thicker wire. The rules set minimum gauges for power, motor, and servo wiring." },
  "strain-relief": { term: "strain relief", def: "Securing a wire near its connector so tugging on the wire does not pull the pins. Zip ties and cable anchors. Most disconnects at competition are missing strain relief." },
  "battery": { term: "battery", aliases: ["12V battery", "NiMH", "robot battery"], def: "Exactly one approved 12 V NiMH pack powers the robot (R601). No LiPo, no second main battery. Charge them properly, number them, and retire the swollen ones.", link: "electronics.html#power" },

  /* ---- software ---- */
  "sdk": { term: "SDK", aliases: ["FTC SDK", "FtcRobotController", "Robot Controller SDK"], def: "The FIRST-provided Android project (FtcRobotController on GitHub) your code lives inside. Version 12.0 shipped for the 2026–27 season; the Robot Controller and Driver Station apps must match.", link: "code.html#setup" },
  "android-studio": { term: "Android Studio", def: "The editor you write and deploy Java FTC code from. Heavy, but it is the official path. Match the version the SDK release notes ask for." },
  "blocks": { term: "Blocks", def: "The drag-and-drop programming option built into the Robot Controller. Fine for a first week, limiting after that." },
  "onbot-java": { term: "OnBot Java", def: "A browser-based Java editor served by the Control Hub itself. No Android Studio needed. Good for quick fixes at a competition." },
  "opmode": { term: "OpMode", aliases: ["OpModes", "op mode"], def: "One runnable program on the robot. You pick it from the Driver Station list. TeleOps and autos are both OpModes.", link: "code.html#opmodes" },
  "linear-opmode": { term: "LinearOpMode", def: "The simplest OpMode style: your code runs top to bottom in runOpMode(), with a while loop for TeleOp." },
  "hardware-map": { term: "hardwareMap", aliases: ["hardware map"], def: "The object that looks up motors, servos, and sensors by the names you gave them in the robot configuration on the Driver Station." },
  "telemetry": { term: "telemetry", def: "Text your code sends to the Driver Station screen each loop. The first debugging tool you should reach for." },
  "command-based": { term: "command-based", aliases: ["command based"], def: "A code structure where each mechanism is a subsystem and each action is a command that can be scheduled, chained, and cancelled. FTCLib and NextFTC bring it to FTC; FRC uses it everywhere." },
  "subsystem": { term: "subsystem", def: "A class that owns one mechanism (the arm, the intake, the drivetrain) and exposes simple methods. Keeps the OpMode small." },
  "state-machine": { term: "state machine", aliases: ["finite state machine", "FSM"], def: "Code organized as a set of named states and the transitions between them. The standard way to write a non-blocking auto or a multi-step TeleOp action." },
  "pid": { term: "PID", aliases: ["PID controller", "PID control"], def: "Proportional-integral-derivative control. Reads the error between where you are and where you want to be and turns it into a motor power. The P term does most of the work.", link: "code.html#control" },
  "feedforward": { term: "feedforward", aliases: ["kF", "kG", "gravity compensation"], def: "Adding a power you already know you will need, like the constant force to hold an arm up against gravity, so the PID only handles the leftovers." },
  "setpoint": { term: "setpoint", aliases: ["target"], def: "The position or velocity you are asking the controller to reach." },
  "overshoot": { term: "overshoot", aliases: ["oscillation", "oscillate"], def: "When a mechanism blows past its target and has to come back. Too much P or too little D. Oscillation is overshooting back and forth forever." },
  "motion-profile": { term: "motion profile", aliases: ["motion profiling", "trapezoidal profile"], def: "A planned speed curve (accelerate, cruise, decelerate) that a controller follows instead of slamming to the target. Smoother and more repeatable." },
  "field-centric": { term: "field-centric", aliases: ["field centric", "field-oriented"], def: "Driving where pushing the stick forward moves the robot away from the driver no matter which way the robot faces. Uses the IMU heading. Easier for drivers on a holonomic base.", see: ["robot-centric"] },
  "robot-centric": { term: "robot-centric", aliases: ["robot centric"], def: "Driving where forward means the robot's forward. Simpler code, more mental load for the driver." },
  "deadband": { term: "deadband", def: "A small stick range near zero you treat as zero so a resting joystick does not creep the robot." },
  "road-runner": { term: "Road Runner", aliases: ["RoadRunner"], def: "A motion-planning library for FTC autonomous. You describe a path of splines and it generates and follows a smooth trajectory. Version 1.0 is the current line." },
  "pedro-pathing": { term: "Pedro Pathing", aliases: ["Pedro"], def: "A newer path-following library built for speed, using Bezier curves and a reactive follower. Popular with top teams; pairs with NextFTC." },
  "ftclib": { term: "FTCLib", def: "A community library that ports FRC's command-based structure and utilities (PID, gamepad helpers, motor wrappers) to FTC." },
  "nextftc": { term: "NextFTC", def: "A command-based library designed to sit on top of Pedro Pathing. The newer alternative to FTCLib." },
  "ftc-dashboard": { term: "FTC Dashboard", aliases: ["Dashboard", "Panels"], def: "A web page served by the robot that graphs telemetry live and lets you tweak variables without redeploying. Panels is the newer replacement with the same idea." },
  "meepmeep": { term: "MeepMeep", def: "A desktop visualizer that draws your Road Runner trajectories on a picture of the field before you run them on a robot." },
  "visionportal": { term: "VisionPortal", aliases: ["vision pipeline", "OpenCV", "EasyOpenCV"], def: "The SDK's camera framework. Runs AprilTag and custom OpenCV processors on a webcam or phone camera." },
  "adb": { term: "ADB", aliases: ["wireless ADB", "adb connect"], def: "Android Debug Bridge. Lets Android Studio deploy code to the Control Hub over Wi-Fi instead of a USB cable." },
  "loop-time": { term: "loop time", aliases: ["loop times", "cycle rate"], def: "How long one pass through your TeleOp loop takes. Slow sensor reads (especially I²C) and unbulked hub reads push it past 50 ms, which makes control mushy." },
  "bulk-read": { term: "bulk reads", aliases: ["bulk read", "bulk caching"], def: "Reading every sensor on a hub in one transaction instead of one at a time. Cuts loop time dramatically. Set the hubs to AUTO or MANUAL caching mode." },
  "git": { term: "Git", aliases: ["GitHub", "version control"], def: "Version control for code. Commit often, push to GitHub, and you can always get back the version that worked at the last event." },
  "mci": { term: "Machine, Creativity & Innovation awards", aliases: ["MCI awards", "Machine awards"], def: "The judged-award group made up of Innovate, Control, and Design. One of the two question-bank questions in every interview is about this group.", link: "judging.html#awards" },
  "team-attributes": { term: "Team Attribute awards", aliases: ["TA awards", "Team Attributes"], def: "The judged-award group made up of Connect, Reach, and Sustain. The other question-bank question in every interview is about this group.", link: "judging.html#awards" },
  "starterbot": { term: "StarterBot", aliases: ["Starter Bot"], def: "Official kit robots from AndyMark, REV, and goBILDA published each season. Their mechanisms are the one exception to the ban on COTS game mechanisms (R301). A fine week-one robot, a poor week-twelve one." },
  "biobuzz": { term: "BIOBUZZ", def: "The 2026–27 FTC game, presented by RTX. Alliances launch POLLEN and NECTAR into the CELLS of a tipping HIVE and place them in FLOWERS on the wall. 30-second auto, 2-minute TeleOp.", link: "history.html" },
  "decode": { term: "DECODE", def: "The 2025–26 FTC game. Score purple and green ARTIFACTS in your GOAL, match PATTERNS on RAMPS to the randomized MOTIF shown on the OBELISK, return to BASE.", link: "history.html" },
  "into-the-deep": { term: "INTO THE DEEP", def: "The 2024–25 FTC game. Collect SAMPLES for the NET ZONE and BASKETS, clip them into SPECIMENS for the CHAMBERS, and ASCEND the SUBMERSIBLE in endgame.", link: "history.html" },
  "expansion": { term: "expansion limit", aliases: ["expansion"], def: "How far the robot may grow after the match starts. For 2026–27: 18 × 24 inches horizontally and 29 inches tall (R105), enforced mechanically, not by software.", link: "design.html#rules" }
};
